import React, { useState, useEffect, useRef } from 'react';
import MeshSphere from '../components/MeshSphere';

const PHASES = [
  { name:'Andas in',  seconds:4, label:'Djupt in — fyll lungorna', hue1:195, hue2:215, speed:0.25, distort:0.1 },
  { name:'Håll',      seconds:7, label:'Håll — var stilla',        hue1:210, hue2:230, speed:0.08, distort:0.05 },
  { name:'Andas ut',  seconds:8, label:'Sakta ut — släpp taget',   hue1:180, hue2:200, speed:0.22, distort:0.12 },
];
const TOTAL = 4;

export default function Breathing({ setPage }) {
  const [running, setRunning] = useState(false);
  const [done,    setDone]    = useState(false);
  const [phase,   setPhase]   = useState(0);
  const [count,   setCount]   = useState(0);
  const [cycle,   setCycle]   = useState(0);
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    setPhase(pi); setCycle(ci); setCount(PHASES[pi].seconds);
    let c = PHASES[pi].seconds;
    timer.current = setInterval(()=>{
      c--; setCount(c);
      if (c<=0){ clearInterval(timer.current); const np=(pi+1)%3; setTimeout(()=>runPhase(np,np===0?ci+1:ci),350); }
    },1000);
  };
  const start = ()=>{ setRunning(true); setDone(false); runPhase(0,0); };
  useEffect(()=>()=>clearInterval(timer.current),[]);
  const cur = PHASES[phase];

  if (done) return (
    <div style={{ minHeight:'100vh', background:'#120e0a', paddingBottom:96, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', position:'relative', overflow:'hidden' }}>
      <div style={{ position:'absolute', top:'50%', left:'50%', transform:'translate(-50%,-58%)', zIndex:0, opacity:0.75 }}>
        <MeshSphere size={360} speed={0.7} distort={0.12} hue1={160} hue2={180} />
      </div>
      <div style={{ position:'relative', zIndex:2, textAlign:'center', padding:'0 24px' }}>
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(240,235,227,0.28)', marginBottom:10 }}>{TOTAL} omgångar · klart</p>
        <h2 style={{ fontFamily:'DM Serif Display,serif', fontSize:36, fontWeight:400, fontStyle:'italic', color:'rgba(240,235,227,0.88)', marginBottom:10 }}>Bra jobbat</h2>
        <p style={{ fontSize:14, color:'rgba(240,235,227,0.4)', marginBottom:36, fontWeight:300 }}>Ditt nervsystem är lugnare nu.</p>
        <div style={{ display:'flex', gap:8, justifyContent:'center' }}>
          <button onClick={()=>setPage('checkin')} style={{ padding:'12px 22px', borderRadius:100, background:'rgba(240,235,227,0.88)', color:'#120e0a', fontSize:13, fontWeight:600, border:'none' }}>Check-in →</button>
          <button onClick={()=>{setDone(false);setRunning(false);}} style={{ padding:'12px 22px', borderRadius:100, background:'rgba(255,255,255,0.06)', border:'1px solid rgba(255,255,255,0.08)', color:'rgba(240,235,227,0.5)', fontSize:13 }}>Igen</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', background:'#120e0a', paddingBottom:96, display:'flex', flexDirection:'column', overflow:'hidden', position:'relative' }}>

      {/* Spiral label on side */}
      <div style={{ position:'fixed', left:18, top:'50%', transform:'translateY(-50%) rotate(-90deg)', zIndex:10, pointerEvents:'none' }}>
        <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(240,235,227,0.15)' }}>Spiral</span>
      </div>

      {/* Phase indicators — centered at top */}
      <div style={{ position:'relative', zIndex:2, textAlign:'center', padding:'28px 22px 0' }}>
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(240,235,227,0.25)', marginBottom:18 }}>4 – 7 – 8 andningsövning</p>
        <div style={{ display:'flex', gap:24, justifyContent:'center' }}>
          {PHASES.map((p, i) => (
            <div key={i} style={{ textAlign:'center' }}>
              <div style={{ fontSize:24, fontWeight:700, letterSpacing:'-0.04em', lineHeight:1, color:running&&phase===i?'rgba(240,235,227,0.9)':'rgba(240,235,227,0.18)', transition:'color .5s' }}>{p.seconds}</div>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, textTransform:'uppercase', letterSpacing:'0.1em', color:running&&phase===i?'rgba(240,235,227,0.45)':'rgba(240,235,227,0.15)', transition:'color .5s', marginTop:3 }}>{p.name}</div>
            </div>
          ))}
        </div>
      </div>

      {/* Orb — main hero */}
      <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', position:'relative' }}>
        <div style={{ position:'relative',
          transition: running
            ? phase===0 ? `transform ${PHASES[0].seconds}s linear`
            : phase===1 ? 'transform .8s ease-out'
            : `transform ${PHASES[2].seconds}s linear`
            : 'transform 1.4s cubic-bezier(0.16,1,0.3,1)',
          transform: running ? (phase<=1 ? 'scale(1.28)' : 'scale(0.80)') : 'scale(1)',
        }}>
          <MeshSphere size={320} speed={running?cur.speed:0.3} distort={running?cur.distort:0.4} hue1={running?cur.hue1:195} hue2={running?cur.hue2:215} />
          {running && (
            <div style={{ position:'absolute', inset:0, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', pointerEvents:'none' }}>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(240,235,227,0.4)', marginBottom:4 }}>{cur.name}</div>
              <div style={{ fontSize:60, fontWeight:700, color:'rgba(240,235,227,0.82)', lineHeight:1, letterSpacing:'-0.05em' }}>{count}</div>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(240,235,227,0.25)', marginTop:6 }}>{cycle+1} / {TOTAL}</div>
            </div>
          )}
        </div>
      </div>

      {/* Bottom */}
      <div style={{ position:'relative', zIndex:2, padding:'0 22px 16px' }}>
        {running ? (
          <div style={{ background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:16, padding:'13px 18px', textAlign:'center', backdropFilter:'blur(10px)' }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.12em', textTransform:'uppercase', color:'rgba(240,235,227,0.4)' }}>{cur.label}</p>
          </div>
        ) : (
          <>
            <h1 style={{ fontFamily:'DM Serif Display,serif', fontSize:'clamp(26px,7vw,40px)', fontWeight:400, fontStyle:'italic', lineHeight:1.1, color:'rgba(240,235,227,0.82)', marginBottom:10 }}>
              Andningsövning
            </h1>
            <p style={{ fontSize:13, color:'rgba(240,235,227,0.38)', fontWeight:300, lineHeight:1.75, marginBottom:20 }}>
              Aktiverar det parasympatiska nervsystemet och reducerar stress på 4 minuter.
            </p>
            <button onClick={start} style={{ width:'100%', padding:'15px', borderRadius:100, background:'rgba(240,235,227,0.88)', color:'#120e0a', fontSize:13, fontWeight:700, border:'none', boxShadow:'0 0 40px rgba(200,190,170,0.1)' }}>
              Starta →
            </button>
          </>
        )}
      </div>
    </div>
  );
}
